CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS worlds(id text PRIMARY KEY, status text NOT NULL CHECK(status IN ('running','archived')), revision bigint NOT NULL, state jsonb NOT NULL, checksum text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_active_world ON worlds((status)) WHERE status='running';
CREATE TABLE IF NOT EXISTS writer_lease(id integer PRIMARY KEY CHECK(id=1), owner text NOT NULL, epoch bigint NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY, username text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS commands(id text PRIMARY KEY, world_id text NOT NULL REFERENCES worlds(id), user_id text REFERENCES users(id), payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', result jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS pending_commands ON commands(world_id,created_at) WHERE status='pending';
CREATE TABLE IF NOT EXISTS journal(world_id text NOT NULL REFERENCES worlds(id),revision bigint NOT NULL,month integer NOT NULL,previous_checksum text NOT NULL,checksum text NOT NULL,patch jsonb NOT NULL,input jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(world_id,revision));
CREATE TABLE IF NOT EXISTS checkpoints(world_id text NOT NULL REFERENCES worlds(id),revision bigint NOT NULL,state jsonb NOT NULL,checksum text NOT NULL,PRIMARY KEY(world_id,revision));
CREATE TABLE IF NOT EXISTS events(cursor bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,id text UNIQUE NOT NULL,world_id text NOT NULL REFERENCES worlds(id),month integer NOT NULL,person_ids text[] NOT NULL,payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS events_person ON events USING gin(person_ids);
CREATE INDEX IF NOT EXISTS events_world_time ON events(world_id,month,cursor);
CREATE TABLE IF NOT EXISTS outbox(cursor bigint PRIMARY KEY REFERENCES events(cursor),world_id text NOT NULL,payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS maps(world_id text NOT NULL REFERENCES worlds(id),month integer NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(world_id,month));
CREATE TABLE IF NOT EXISTS jobs(id text PRIMARY KEY,world_id text NOT NULL REFERENCES worlds(id),actor_id text NOT NULL,actor_version integer NOT NULL,observed_month integer NOT NULL,deadline integer NOT NULL,kind text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',result jsonb,audit jsonb,attempts integer NOT NULL DEFAULT 0,claimed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS jobs_pending ON jobs(created_at) WHERE status='pending';
CREATE TABLE IF NOT EXISTS admin_audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,action text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings(key text PRIMARY KEY,value jsonb NOT NULL);
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS narratives(id text PRIMARY KEY,world_id text NOT NULL REFERENCES worlds(id),person_id text NOT NULL,month integer NOT NULL,source_ids text[] NOT NULL,paragraphs jsonb NOT NULL,generator text NOT NULL);
CREATE INDEX IF NOT EXISTS narratives_person ON narratives(world_id,person_id,month);
CREATE TABLE IF NOT EXISTS model_budget(day date NOT NULL,bucket text NOT NULL,tokens integer NOT NULL CHECK(tokens>=0),PRIMARY KEY(day,bucket));
CREATE TABLE IF NOT EXISTS model_calls(id text PRIMARY KEY,actor_id text NOT NULL,reserved integer NOT NULL,tokens integer,status text NOT NULL,model text,prompt_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION slw_immutable_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Committed history is immutable'; END $$;
DROP TRIGGER IF EXISTS immutable_events ON events;
CREATE TRIGGER immutable_events BEFORE UPDATE OR DELETE ON events FOR EACH ROW EXECUTE FUNCTION slw_immutable_history();
DROP TRIGGER IF EXISTS immutable_journal ON journal;
CREATE TRIGGER immutable_journal BEFORE UPDATE OR DELETE ON journal FOR EACH ROW EXECUTE FUNCTION slw_immutable_history();
CREATE OR REPLACE FUNCTION slw_sealed_world() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='archived' THEN RAISE EXCEPTION 'Archived world is immutable'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS sealed_world ON worlds;
CREATE TRIGGER sealed_world BEFORE UPDATE ON worlds FOR EACH ROW EXECUTE FUNCTION slw_sealed_world();
